import{_ as t,c as a,a3 as o,o as n}from"./chunks/framework.BSKDiXd-.js";const u=JSON.parse('{"title":"SVG Graphane Object","description":"","frontmatter":{},"headers":[],"relativePath":"reference/svg/lib/index.md","filePath":"reference/svg/lib/index.md"}'),r={name:"reference/svg/lib/index.md"};function c(i,e,s,l,d,h){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="svg-graphane-object" tabindex="-1">SVG Graphane Object <a class="header-anchor" href="#svg-graphane-object" aria-label="Permalink to &quot;SVG Graphane Object&quot;">​</a></h1><p><strong>Graphane</strong> includes a powerful API to simplify the construction and manipulation of SVG graphics from Javascript. The API is very close to the SVG structure.</p><p>You can access the SVG with the Graphane API from the methods included in the component with:</p><ul><li><code>$. $.svg</code>.</li></ul><p>You can also access it from outside the component with:</p><ul><li><code>&lt;component&gt;.svg</code></li></ul><p>In Graphane SVG wrapper, all are methods; thus, when you want to work with SVG attributes or properties, you must use methods. For example, set an <code>id</code> to an SVG element is <code>element.id(&#39;unique_id&#39;)</code> and for getting this identification it is necessary to use <code>element.id()</code>.</p><p>Graphane dynamically constructs the methods, which can chain together to make successive calls. Each call returns the original object and can include one call after another.</p>',8)]))}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
